//! Algorithms on permutation groups given by generators and a stabiliser chain (Seress, *Permutation Group
//! Algorithms*, ch. 2-6; Holt, Eick and O'Brien, *Handbook of Computational Group Theory*, ch. 4).
use crate::chain::Chain;
use crate::perm::{self, Perm};
use crate::Ctl;
use mc_eval::Res;
use std::collections::HashSet;

/// A permutation group of degree n: its generators and a stabiliser chain.
#[derive(Clone, Debug)]
pub struct Group {
    pub n: usize,
    pub gens: Vec<Perm>,
    pub chain: Chain,
}

impl Group {
    /// The group generated by `gens` (identities dropped), all of degree n.
    pub fn new(n: usize, gens: Vec<Perm>, ctl: &Ctl) -> Res<Group> {
        let gens: Vec<Perm> = gens.into_iter().filter(|g| !perm::is_identity(g)).collect();
        let chain = Chain::new(n, &gens, &[], ctl)?;
        Ok(Group { n, gens, chain })
    }

    /// The group with a chain whose base begins with `prefix`.
    pub fn with_base(&self, prefix: &[u32], ctl: &Ctl) -> Res<Chain> {
        Chain::new(self.n, &self.chain.strong_gens(), prefix, ctl)
    }

    pub fn order(&self) -> Option<u128> {
        self.chain.order_u128()
    }

    pub fn contains(&self, g: &[u32]) -> bool {
        self.chain.contains(g)
    }

    /// Whether every generator of `h` is in this group.
    pub fn contains_group(&self, h: &Group) -> bool {
        h.gens.iter().all(|g| self.contains(g))
    }

    pub fn is_trivial(&self) -> bool {
        self.chain.levels.iter().all(|l| l.orbit.len() == 1)
    }

    /// Whether the groups are equal (`h` a subgroup of the same order).
    pub fn same(&self, h: &Group) -> bool {
        self.chain.order() == h.chain.order() && self.contains_group(h)
    }
}

/// The orbit of the point x, in the order found (breadth first).
pub fn orbit(n: usize, gens: &[Perm], x: u32) -> Vec<u32> {
    let mut seen = vec![false; n];
    seen[x as usize] = true;
    let mut out = vec![x];
    let mut k = 0;
    while k < out.len() {
        let y = out[k];
        for g in gens {
            let z = g[y as usize];
            if !seen[z as usize] {
                seen[z as usize] = true;
                out.push(z);
            }
        }
        k += 1;
    }
    out
}

/// The orbits on {0, ..., n-1}, each sorted, ordered by their least points.
pub fn orbits(n: usize, gens: &[Perm]) -> Vec<Vec<u32>> {
    let mut seen = vec![false; n];
    let mut out = Vec::new();
    for x in 0..n {
        if !seen[x] {
            let mut o = orbit(n, gens, x as u32);
            for &y in &o {
                seen[y as usize] = true;
            }
            o.sort_unstable();
            out.push(o);
        }
    }
    out
}

/// The pointwise stabiliser of the points.
pub fn stabilizer(g: &Group, points: &[u32], ctl: &Ctl) -> Res<Group> {
    let c = g.with_base(points, ctl)?;
    let gens = c.gens_from(points.len());
    let chain = Chain::new(g.n, &gens, &[], ctl)?;
    Ok(Group { n: g.n, gens, chain })
}

/// The normal closure of the elements `xs` in g.
pub fn normal_closure(g: &Group, xs: &[Perm], ctl: &Ctl) -> Res<Group> {
    let mut chain = Chain::trivial(g.n);
    let mut gens: Vec<Perm> = Vec::new();
    let mut queue: Vec<Perm> = xs.iter().filter(|x| !perm::is_identity(x)).cloned().collect();
    while let Some(x) = queue.pop() {
        if chain.contains(&x) {
            continue;
        }
        chain.extend(0, x.clone(), ctl)?;
        for s in &g.gens {
            queue.push(perm::conj(&x, s));
        }
        gens.push(x);
    }
    Ok(Group { n: g.n, gens, chain })
}

/// The subgroup generated by `xs`.
pub fn subgroup(n: usize, xs: Vec<Perm>, ctl: &Ctl) -> Res<Group> {
    Group::new(n, xs, ctl)
}

/// The commutator subgroup [a, b] of two subgroups normalised by g (as the normal closure in g).
pub fn commutator_in(g: &Group, a: &Group, b: &Group, ctl: &Ctl) -> Res<Group> {
    let mut cs = Vec::new();
    for x in &a.gens {
        for y in &b.gens {
            cs.push(perm::comm(x, y));
        }
    }
    normal_closure(g, &cs, ctl)
}

pub fn derived_subgroup(g: &Group, ctl: &Ctl) -> Res<Group> {
    commutator_in(g, g, g, ctl)
}

/// The derived series G > G' > G'' > ..., until it is stable.
pub fn derived_series(g: &Group, ctl: &Ctl) -> Res<Vec<Group>> {
    let mut out = vec![g.clone()];
    loop {
        let last = out.last().expect("the series is not empty");
        let d = derived_subgroup(last, ctl)?;
        if d.chain.order() == last.chain.order() {
            return Ok(out);
        }
        out.push(d);
    }
}

/// The lower central series G = g_1 > g_2 = [G, G] > g_3 = [g_2, G] > ..., until it is stable.
pub fn lower_central_series(g: &Group, ctl: &Ctl) -> Res<Vec<Group>> {
    let mut out = vec![g.clone()];
    loop {
        let last = out.last().expect("the series is not empty");
        let d = commutator_in(g, last, g, ctl)?;
        if d.chain.order() == last.chain.order() {
            return Ok(out);
        }
        out.push(d);
    }
}

pub fn is_solvable(g: &Group, ctl: &Ctl) -> Res<bool> {
    Ok(derived_series(g, ctl)?.last().expect("the series is not empty").is_trivial())
}

pub fn is_nilpotent(g: &Group, ctl: &Ctl) -> Res<bool> {
    Ok(lower_central_series(g, ctl)?.last().expect("the series is not empty").is_trivial())
}

pub fn is_abelian(g: &Group) -> bool {
    g.gens.iter().enumerate().all(|(i, a)| g.gens[i + 1..].iter().all(|b| perm::mul(a, b) == perm::mul(b, a)))
}

/// Whether h is normal in g (h a subgroup of g): every conjugate of a generator of h by one of g lies in h.
pub fn is_normal(g: &Group, h: &Group) -> bool {
    h.gens.iter().all(|x| g.gens.iter().all(|s| h.contains(&perm::conj(x, s))))
}

/// Representatives of the right cosets H x of h in g (h a subgroup of g), the identity first, found by a breadth
/// first search over the cosets with canonical representatives ([`Chain::coset_rep`]); `None` past `limit`.
pub fn right_cosets(g: &Group, h: &Group, limit: usize, ctl: &Ctl) -> Res<Option<Vec<Perm>>> {
    let id = perm::identity(g.n);
    let mut seen: HashSet<Perm> = HashSet::new();
    seen.insert(h.chain.coset_rep(id.clone()));
    let mut reps = vec![id];
    let mut k = 0;
    while k < reps.len() {
        for s in &g.gens {
            let x = perm::mul(&reps[k], s);
            let c = h.chain.coset_rep(x.clone());
            if seen.insert(c) {
                reps.push(x);
                if reps.len() > limit {
                    return Ok(None);
                }
            }
        }
        ctl.step(g.n as u64)?;
        k += 1;
    }
    Ok(Some(reps))
}

/// The minimal block system in which the points a and b share a block (Atkinson's algorithm with union-find, for a
/// transitive group; Seress 5.5): the blocks, each sorted, ordered by their least points.
pub fn minimal_blocks(n: usize, gens: &[Perm], a: u32, b: u32) -> Vec<Vec<u32>> {
    let mut parent: Vec<u32> = (0..n as u32).collect();
    fn find(p: &mut [u32], mut x: u32) -> u32 {
        while p[x as usize] != x {
            p[x as usize] = p[p[x as usize] as usize];
            x = p[x as usize];
        }
        x
    }
    let mut queue = vec![(a, b)];
    {
        let (ra, rb) = (find(&mut parent, a), find(&mut parent, b));
        if ra != rb {
            parent[ra.max(rb) as usize] = ra.min(rb);
        }
    }
    while let Some((x, y)) = queue.pop() {
        for g in gens {
            let (gx, gy) = (g[x as usize], g[y as usize]);
            let (rx, ry) = (find(&mut parent, gx), find(&mut parent, gy));
            if rx != ry {
                parent[rx.max(ry) as usize] = rx.min(ry);
                queue.push((gx, gy));
            }
        }
    }
    let mut blocks: Vec<Vec<u32>> = Vec::new();
    let mut index = vec![usize::MAX; n];
    for x in 0..n as u32 {
        let r = find(&mut parent, x) as usize;
        if index[r] == usize::MAX {
            index[r] = blocks.len();
            blocks.push(Vec::new());
        }
        blocks[index[r]].push(x);
    }
    blocks
}

/// A block system with the least nontrivial blocks of a transitive group on {0..n-1}, or `None` when the group is
/// primitive (every minimal block containing 0 and another point is the whole set).
pub fn nontrivial_blocks(n: usize, gens: &[Perm]) -> Option<Vec<Vec<u32>>> {
    let mut best: Option<Vec<Vec<u32>>> = None;
    for b in 1..n as u32 {
        let bs = minimal_blocks(n, gens, 0, b);
        if bs.len() > 1 && best.as_ref().is_none_or(|x| bs[0].len() < x[0].len()) {
            best = Some(bs);
        }
    }
    best
}

/// The composition series G = G_0 > G_1 > ... > G_r = 1 with simple factors.
///
/// Solvable steps are refined through the derived series: in an abelian quotient G/N the subgroups
/// N < <N, g_1> < <N, g_1, g_2> < ... are normal, and the cyclic step of order m is cut into prime steps by powers.
/// A perfect step is split at a maximal normal subgroup, found from the normal closures of the conjugacy class
/// representatives (every normal subgroup is a join of such closures; adding closures while the join stays proper
/// ends at a maximal one); the step is simple when every closure is the whole group.
pub fn composition_series(g: &Group, ctl: &Ctl) -> Res<Option<Vec<Group>>> {
    let mut out = vec![g.clone()];
    let mut cur = g.clone();
    while !cur.is_trivial() {
        let d = derived_subgroup(&cur, ctl)?;
        if d.chain.order() != cur.chain.order() {
            // the abelian layer cur > d, refined top down
            let mut layer = vec![d.clone()];
            let mut gens = d.gens.clone();
            for s in &cur.gens {
                let below = layer.last().expect("the layer is not empty").clone();
                if below.contains(s) {
                    continue;
                }
                // the order m of s modulo `below`
                let mut m = 1u64;
                let mut x = s.clone();
                while !below.contains(&x) {
                    x = perm::mul(&x, s);
                    m += 1;
                }
                // below < <below, s^(m/p1)> < <below, s^(m/(p1 p2))> < ... < <below, s>
                let mut primes = Vec::new();
                let mut r = m;
                let mut p = 2;
                while r > 1 {
                    while r.is_multiple_of(p) {
                        primes.push(p);
                        r /= p;
                    }
                    p += 1;
                }
                let mut e = m;
                for p in primes {
                    e /= p;
                    let mut gg = gens.clone();
                    gg.push(perm::pow(s, e as i64));
                    layer.push(Group::new(g.n, gg, ctl)?);
                }
                gens.push(s.clone());
            }
            // layer is d < ... < cur (the last equals cur); add it top down
            layer.pop();
            while let Some(x) = layer.pop() {
                out.push(x);
            }
            cur = d;
            continue;
        }
        // perfect: a maximal normal subgroup
        let Some(reps) = crate::classes::class_reps_any(&cur, ctl)? else { return Ok(None) };
        let mut closures: Vec<Group> = Vec::new();
        for r in reps.iter().filter(|r| !perm::is_identity(r)) {
            let c = normal_closure(&cur, std::slice::from_ref(r), ctl)?;
            if c.chain.order() != cur.chain.order() {
                closures.push(c);
            }
        }
        let Some(first) = closures.first().cloned() else {
            out.push(Group::new(g.n, Vec::new(), ctl)?);
            break;
        };
        let mut m = first;
        for c in &closures[1..] {
            if m.contains_group(c) {
                continue;
            }
            let mut gg = m.gens.clone();
            gg.extend(c.gens.iter().cloned());
            let j = normal_closure(&cur, &gg, ctl)?;
            if j.chain.order() != cur.chain.order() {
                m = j;
            }
        }
        out.push(m.clone());
        cur = m;
    }
    Ok(Some(out))
}

/// The invariants of the abelianisation G/G' (as elementary divisors, prime powers in increasing order): for each
/// prime p dividing |G/G'|, |G : G' G^(p^k)| counts the cyclic p-factors of order at least p^k (in an abelian group
/// the p^k-th powers of the generators generate the p^k-th powers).
pub fn abelian_invariants(g: &Group, ctl: &Ctl) -> Res<Option<Vec<u128>>> {
    let d = derived_subgroup(g, ctl)?;
    let (Some(og), Some(od)) = (g.order(), d.order()) else { return Ok(None) };
    let m = og / od;
    let mut r = m;
    let mut primes = Vec::new();
    let mut p = 2u128;
    while r > 1 {
        if r % p == 0 {
            primes.push(p);
            while r % p == 0 {
                r /= p;
            }
        }
        p += 1;
    }
    let mut out = Vec::new();
    for p in primes {
        // index of G' G^(p^k) for k = 0, 1, ...
        let mut prev = 1u128;
        let mut q = p;
        let mut counts = Vec::new();
        loop {
            let mut gens = d.gens.clone();
            for s in &g.gens {
                gens.push(perm::pow(s, q as i64));
            }
            let h = Group::new(g.n, gens, ctl)?;
            let idx = og / h.order().unwrap_or(1);
            if idx == prev {
                break;
            }
            let mut c = 0;
            let mut t = idx / prev;
            while t > 1 {
                t /= p;
                c += 1;
            }
            counts.push(c);
            prev = idx;
            q *= p;
        }
        // counts[k] = number of factors of order >= p^(k+1)
        for k in 0..counts.len() {
            let ge = counts[k];
            let gt = counts.get(k + 1).copied().unwrap_or(0);
            for _ in 0..(ge - gt) {
                out.push(p.pow(k as u32 + 1));
            }
        }
    }
    out.sort_unstable();
    Ok(Some(out))
}
